-- A deposit past the request cap arrives in parts (t880). `batch` is the SHA-256 of the whole batch as the client hashed it, so a retried part lands on its own row and changes nothing. The parts wait here, outside the ledger, until all `count` of them are held; the server then checks their join against `batch`, stores the one deposit, and clears each `body` and sets `deposit` to its session id, so a part sent again after the deposit finished is answered from the row. A row is a marker of about a hundred bytes once its body is cleared.
CREATE TABLE deposit_parts (account TEXT NOT NULL REFERENCES accounts(id), batch TEXT NOT NULL, part INTEGER NOT NULL, count INTEGER NOT NULL, body TEXT NOT NULL, deposit TEXT, PRIMARY KEY (account, batch, part)) STRICT, WITHOUT ROWID;
